/// What went wrong, as a message the user can act on.
#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum MobileError {
    /// A command failed or was refused: unknown id, bad parameters, nothing to act on…
    #[error("{0}")]
    Command(String),
    /// A file could not be imported.
    #[error("{0}")]
    Import(String),
    /// There is no sequence open.
    #[error("no sequence is open")]
    NoSequence,
    /// A frame could not be drawn.
    #[error("{0}")]
    Render(String),
}

impl From<filmcraft_engine::EngineError> for MobileError {
    fn from(e: filmcraft_engine::EngineError) -> Self {
        match e {
            filmcraft_engine::EngineError::NoSequence => MobileError::NoSequence,
            e => MobileError::Command(e.to_string()),
        }
    }
}

/// The open sequence as the editor shows it.
#[derive(Debug, Clone, uniffi::Record)]
pub struct SequenceInfo {
    /// The item id of the sequence in the project.
    pub id: u64,
    pub name: String,
    /// Frame size in pixels.
    pub width: u32,
    pub height: u32,
    /// Frame rate as a fraction (30000/1001 for 29.97).
    pub rate_num: i64,
    pub rate_den: i64,
    /// Length in ticks.
    pub duration: i64,
    /// The playhead, in ticks.
    pub playhead: i64,
}

/// A picture of the program: straight (not premultiplied) sRGB RGBA, 8 bits a channel, rows top
/// to bottom with no padding.
#[derive(Debug, Clone, uniffi::Record)]
pub struct Frame {
    pub width: u32,
    pub height: u32,
    /// The time drawn (snapped to the sequence's frame), in ticks.
    pub time: i64,
    pub rgba: Vec<u8>,
}

/// One imported file.
#[derive(Debug, Clone, uniffi::Record)]
pub struct ImportedItem {
    pub id: u64,
    pub name: String,
}

/// The session's state that the editor's chrome shows: undo/redo and unsaved changes.
#[derive(Debug, Clone, uniffi::Record)]
pub struct SessionStatus {
    /// Changes with every edit, undo and redo: re-read the timeline when it does.
    pub revision: u64,
    pub dirty: bool,
    pub can_undo: bool,
    pub can_redo: bool,
    pub undo_label: Option<String>,
    pub redo_label: Option<String>,
    /// Messages the engine wants shown (errors of background work, recovered projects…).
    pub messages: Vec<String>,
}

/// Ticks per second, for the UI's clock and labels.
#[uniffi::export]
pub fn ticks_per_second() -> i64 {
    TICKS_PER_SECOND
}

