/// Give back memory kept for later: an export's frame buffers and the natural voices' model. Call
/// when an export ends, when the editor closes and when the system asks the app to use less.
#[uniffi::export]
pub fn trim_memory() {
    filmcraft_frame::pool::trim_f32();
    // the natural voices' model: loaded again (a few seconds) the next time a voice speaks
    filmcraft_tts::neural::unload();
}

